window.ScripturaLexicons.BDAG_PART_0010 = {source:"BDAG", searchAnchorId:"bdag-search-anchor", entryAnchorId:"bdag-entry-anchor", rowsHtml:"<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-adam-bdag\" data-source=\"BDAG\" data-search=\"Ἀδάμ Adam Adão אָדָם primeiro ser humano Cristo humanidade BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Ἀδάμ</td><td>Nome próprio</td><td>Adão</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-adapanos-bdag\" data-source=\"BDAG\" data-search=\"ἀδάπανος adapanos gratuito sem custo sem despesa evangelho BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀδάπανος</td><td>Adjetivo</td><td>gratuito; sem custo</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-addi-bdag\" data-source=\"BDAG\" data-search=\"Ἀδδί Addi Adi genealogia Jesus Lucas BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Ἀδδί</td><td>Nome próprio</td><td>Adi</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-adelphe-bdag\" data-source=\"BDAG\" data-search=\"ἀδελφή adelphe irmã literal fé comunidade irmã BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀδελφή</td><td>Substantivo</td><td>irmã</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-adelphoktonia-bdag\" data-source=\"BDAG\" data-search=\"ἀδελφοκτονία adelphoktonia fratricídio Caim BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀδελφοκτονία</td><td>Substantivo</td><td>fratricídio</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-adelphos-bdag\" data-source=\"BDAG\" data-search=\"ἀδελφός adelphos irmão irmãos irmãs companheiro membro compatriota próximo BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀδελφός</td><td>Substantivo</td><td>irmão; companheiro; membro; compatriota; próximo</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-adelphotes-bdag\" data-source=\"BDAG\" data-search=\"ἀδελφότης adelphotes fraternidade comunidade irmãos afeição fraternal BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀδελφότης</td><td>Substantivo</td><td>fraternidade; comunidade; afeição fraternal</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-adeos-bdag\" data-source=\"BDAG\" data-search=\"ἀδεῶς adeos sem medo sem perturbação BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀδεῶς</td><td>Advérbio</td><td>sem medo; sem perturbação</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-adelos-bdag\" data-source=\"BDAG\" data-search=\"ἄδηλος adelos não claro oculto invisível indistinto BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἄδηλος</td><td>Adjetivo</td><td>não claro; oculto; invisível; indistinto</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-adelotes-bdag\" data-source=\"BDAG\" data-search=\"ἀδηλότης adelotes incerteza riqueza BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀδηλότης</td><td>Substantivo</td><td>incerteza</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-adelos-adv-bdag\" data-source=\"BDAG\" data-search=\"ἀδήλως adelos advérbio incertamente sem alvo BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀδήλως</td><td>Advérbio</td><td>incertamente; sem alvo</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-ademoneo-bdag\" data-source=\"BDAG\" data-search=\"ἀδημονέω ademoneo angustiado aflito perturbado ansioso BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀδημονέω</td><td>Verbo</td><td>angustiar-se; afligir-se; estar perturbado</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-hades-bdag\" data-source=\"BDAG\" data-search=\"ᾅδης hades Hades mundo dos mortos morte inferno BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ᾅδης</td><td>Substantivo / nome próprio</td><td>Hades; mundo dos mortos</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-adiakritos-bdag\" data-source=\"BDAG\" data-search=\"ἀδιάκριτος adiakritos imparcial não divisivo sem hesitação firme BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀδιάκριτος</td><td>Adjetivo</td><td>imparcial; não divisivo; firme</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-adiakritos-adv-bdag\" data-source=\"BDAG\" data-search=\"ἀδιακρίτως adiakritos advérbio sem hesitar sem vacilar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀδιακρίτως</td><td>Advérbio</td><td>sem hesitar; sem vacilar</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-adialeiptos-bdag\" data-source=\"BDAG\" data-search=\"ἀδιάλειπτος adialeiptos incessante constante contínuo BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀδιάλειπτος</td><td>Adjetivo</td><td>incessante; constante</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-adialeiptos-adv-bdag\" data-source=\"BDAG\" data-search=\"ἀδιαλείπτως adialeiptos advérbio constantemente incessantemente sem cessar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀδιαλείπτως</td><td>Advérbio</td><td>constantemente; incessantemente</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-adiaphthoria-bdag\" data-source=\"BDAG\" data-search=\"ἀδιαφθορία adiaphthoria sinceridade integridade BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀδιαφθορία</td><td>Substantivo</td><td>sinceridade; integridade</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-adiegetos-bdag\" data-source=\"BDAG\" data-search=\"ἀδιήγητος adiegetos indescritível inexprimível BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀδιήγητος</td><td>Adjetivo</td><td>indescritível; inexprimível</td><td><span class=\"source-pill\">BDAG</span></td></tr>", cardsHtml:"<article id=\"entry-adam-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Ἀδάμ</h1><div class=\"entry-meta\"><span class=\"article greek\">ὁ</span><span class=\"separator\">·</span><span class=\"transliteration\">⟦Adám⟧</span><span class=\"separator\">·</span><span>indeclinável</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">\n(<bdi class=\"hebrew hebrew-token tooltip-trigger\" lang=\"he\" dir=\"rtl\" tabindex=\"0\" data-tooltip-type=\"hebrew\" data-tooltip-label=\"אָדָם\" data-transliteration=\"ʾāḏām\" data-meanings=\"Adão|ser humano\">אָדָם</bdi>; LXX, pseudoepígrafos, Fílon, Just.; Mel., <em>P.</em> 83. — Em Josefo, <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"Ἄδαμος, ου\" data-meanings=\"Adão; forma declinada em Josefo\">Ἄδαμος, ου</span> [<em>Ant.</em> 1, 66].) <strong>Adão, o primeiro ser humano</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.2.13\" target=\"_blank\" rel=\"noopener noreferrer\">1 Tm 2.13</a>; <span class=\"biblio-ref tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"biblio\" data-tooltip-label=\"B 6:9\" data-tooltip-text=\"Epístola de Barnabé 6:9\">B 6:9</span> (compare <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/GEN.1.27\" target=\"_blank\" rel=\"noopener noreferrer\">Gn 1.27 ss.</a>). <strong>Ancestral da humanidade</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.5.14\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 5.14</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JUD.1.14\" target=\"_blank\" rel=\"noopener noreferrer\">Jd 14</a>; 1 Cl 50:3. Daí <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"πατὴρ ἡμῶν\" data-meanings=\"nosso pai\">πατὴρ ἡμῶν</span> 1 Cl 6:3; as pessoas são <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"υἱοὶ Ἀ.\" data-meanings=\"filhos de Adão\">υἱοὶ Ἀ.</span> 29:2 (compare <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/DEU.32.8\" target=\"_blank\" rel=\"noopener noreferrer\">Dt 32.8</a>). Na genealogia de Jesus, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.3.38\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 3.38</a>. Sua queda, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.5.14\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 5.14</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.2.14\" target=\"_blank\" rel=\"noopener noreferrer\">1 Tm 2.14</a>. Enquanto Adão orava, Eva foi seduzida pela serpente, GJs 13:1 (ApcMos 17).\nAlguns sustentam que existia a concepção de que, no fim do mundo, os acontecimentos iniciais se repetiriam e, por isso, Adão, por quem todos perecem, é contrastado com Cristo, que dá vida a todos, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.15.22\" target=\"_blank\" rel=\"noopener noreferrer\">1 Co 15.22</a> (H. Gunkel, <em>Schöpfung u. Chaos</em> 1895). O paralelo entre Adão e Cristo e a designação de Cristo como “futuro” em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.5.14\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 5.14</a> são bem conhecidos. É discutível se o conhecido mito (gnóstico) do primeiro ser humano como deus-redentor influenciou Paulo diretamente ou se ele chegou à sua concepção por percepções judaicas (Bousset, <em>Kyrios Christos</em>² 1921, 140–145; Rtzst., <em>Erlösungsmyst.</em> 107 ss.; veja <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἄνθρωπος\" data-meanings=\"ser humano\">ἄνθρωπος</span> 1d). Sobre o debate estimulado por K. Barth, <em>Christus u. Adam nach Römer 5</em>, 1952: R. Bultmann, “Adam u. Christus nach Röm. 5”, ZNW 50, 1959, 145–168; E. Brandenburger, <em>Adam u. Christus</em>, 1962; E. Jüngel, ZTK 60, 1963, 42–74.\n— B. Murmelstein, “Adam. E. Beitrag z. Messiaslehre”, <em>Wiener Ztschr. f. d. Kunde d. Morgenlandes</em> 35, 1928, 242–275; 36, 1929, 51–86; Ltzm., excursus sobre <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.15.45\" target=\"_blank\" rel=\"noopener noreferrer\">1 Co 15.45–49</a>; A. Vitti, “Christus-Adam”, <em>Biblica</em> 7, 1926, 121–145; 270–285; 384–401; A. Rawlinson, <em>The NT Doctrine of the Christ</em> 1926, 124 ss.; C. Kraeling, <em>Anthropos and the Son of Man</em>, 1927; A. Marmorstein, ZNW 30, 1931, 271–277; O. Kuss, <em>Ro 5:12–21. D. Adam-Christusparallele</em>, diss. Breslau 1930; G. Westberg, “The Two Adams”, BiblSacra 94, 1937, 37–50; A. Röder, <em>D. Gesch.-philos. des Ap. Pls.</em>, diss. Freiburg 1938; S. Hanson, <em>Unity of the Church in the NT</em>, 1946, 66–73; R. Scroggs, <em>The Last Adam</em>, 1966 (bibliografia 123–128); J. Fitzmyer, <em>ABComm Romans</em> 423–428 (bibliografia). — EDNT. TW.\n</p></section></article><article id=\"entry-adapanos-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀδάπανος</h1><div class=\"entry-meta\"><span class=\"greek\">ον</span><span class=\"separator\">·</span><span class=\"transliteration\">⟦adápanos⟧</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">\n(Aristoph., <em>Pax</em> 593; Teles 7, 8 e outros; Michel 1006, 21 = CIG 3065 [séc. II a.C.] <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀδάπανον τὴν συμμορίαν καθιστάνει\" data-meanings=\"tornar a associação livre de despesa\">ἀδάπανον τὴν συμμορίαν καθιστάνει</span>). <strong>Livre de custo, gratuito</strong>, característica de muitos benfeitores greco-romanos (Danker, <em>Benefactor</em> 332–336): <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἵνα ἀ. θήσω τὸ εὐαγγέλιον\" data-meanings=\"para que eu torne o evangelho gratuito\">ἵνα ἀ. θήσω τὸ εὐαγγέλιον</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.9.18\" target=\"_blank\" rel=\"noopener noreferrer\">1 Co 9.18</a>. — DELG s.v. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"δάπτω\" data-meanings=\"consumir; devorar\">δάπτω</span>. M-M.\n</p></section></article><article id=\"entry-addi-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Ἀδδί</h1><div class=\"entry-meta\"><span class=\"article greek\">ὁ</span><span class=\"separator\">·</span><span class=\"transliteration\">⟦Addí⟧</span><span class=\"separator\">·</span><span>indeclinável</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">\n<strong>Adi</strong>, na genealogia de Jesus, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.3.28\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 3.28</a> (<span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"Ἀδδει\" data-meanings=\"Adi; leitura variante\">Ἀδδει</span> Tdf.; W-H., S., Vog.).\n</p></section></article><article id=\"entry-adelphe-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀδελφή</h1><div class=\"entry-meta\"><span class=\"greek\">ῆς, ἡ</span><span class=\"separator\">·</span><span class=\"transliteration\">⟦adelphḗ⟧</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">\n(Ésquilo+.)\n<span class=\"sense-number\">1.</span> <strong>Mulher proveniente do mesmo ventre que a pessoa de referência, irmã</strong>, literalmente: <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.19.29\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 19.29</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.10.29\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 10.29 s.</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.10.39\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 10.39 s.</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.14.26\" target=\"_blank\" rel=\"noopener noreferrer\">14.26</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.11.1\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 11.1</a>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.11.3\" target=\"_blank\" rel=\"noopener noreferrer\">3</a>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.11.5\" target=\"_blank\" rel=\"noopener noreferrer\">5</a>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.11.28\" target=\"_blank\" rel=\"noopener noreferrer\">28</a>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.11.39\" target=\"_blank\" rel=\"noopener noreferrer\">39</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.19.25\" target=\"_blank\" rel=\"noopener noreferrer\">19.25</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.16.15\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 16.15</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.5.2\" target=\"_blank\" rel=\"noopener noreferrer\">1 Tm 5.2</a>. Das irmãs de Jesus (veja <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀδελφός\" data-meanings=\"irmão\">ἀδελφός</span> 1), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.13.56\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 13.56</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.3.32\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 3.32</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.6.3\" target=\"_blank\" rel=\"noopener noreferrer\">6.3</a>. Irmã de Paulo, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.23.16\" target=\"_blank\" rel=\"noopener noreferrer\">At 23.16</a>.\n<span class=\"sense-number\">2.</span> <strong>Pessoa ou coisa vista como irmã em relação a outra entidade, irmã</strong>, metaforicamente.\n<strong>a.</strong> De uma mulher que compartilha as crenças da pessoa de referência ou de outros numa comunidade de fé, <strong>irmã</strong>. Usado por Jesus de relação espiritual, não natural, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.12.50\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 12.50</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.3.35\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 3.35</a>. Semelhantemente <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀγαπᾶν ὡς ἀ.\" data-meanings=\"amar como irmã\">ἀγαπᾶν ὡς ἀ.</span> Hv 1, 1, 1; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἐντρέπεσθαι ὡς ἀ.\" data-meanings=\"respeitar como irmã\">ἐντρέπεσθαι ὡς ἀ.</span> v 1, 1, 7. Em relação comunitária: <strong>irmã na fé</strong> (como hebraico <bdi class=\"hebrew hebrew-token tooltip-trigger\" lang=\"he\" dir=\"rtl\" tabindex=\"0\" data-tooltip-type=\"hebrew\" data-tooltip-label=\"אָחוֹת\" data-transliteration=\"ʾāḥôṯ\" data-meanings=\"irmã\">אָחוֹת</bdi>; “irmã” = compatriota em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/NUM.25.18\" target=\"_blank\" rel=\"noopener noreferrer\">Nm 25.18</a>; veja <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀδελφός\" data-meanings=\"irmão\">ἀδελφός</span> 2 e compare PGM 4, 1135–1137 <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"χαίρετε, οἷς τὸ χαίρειν ἐν εὐλογίᾳ δίδοται, ἀδελφοῖς καὶ ἀδελφαῖς, ὁσίοις καὶ ὁσίαις\" data-meanings=\"saudações aos irmãos e irmãs, santos e santas, a quem é dado alegrar-se em bênção\">χαίρετε, οἷς τὸ χαίρειν ἐν εὐλογίᾳ δίδοται, ἀδελφοῖς καὶ ἀδελφαῖς, ὁσίοις καὶ ὁσίαις</span>), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.16.1\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 16.1</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.7.15\" target=\"_blank\" rel=\"noopener noreferrer\">1 Co 7.15</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.9.5\" target=\"_blank\" rel=\"noopener noreferrer\">9.5</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHM.1.2\" target=\"_blank\" rel=\"noopener noreferrer\">Fm 2</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.2.15\" target=\"_blank\" rel=\"noopener noreferrer\">Tg 2.15</a>; IPol 5:1; 2 Cl 12:5; Hv 2, 2, 3; 2, 3, 1; Ox 3525, 15. Em tratamento, com <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀδελφοί\" data-meanings=\"irmãos\">ἀδελφοί</span>, 2 Cl 19:1; 20:2.\n<strong>b.</strong> De relação estreita entre comunidades semelhantes (OGI 536, 5), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2JN.1.13\" target=\"_blank\" rel=\"noopener noreferrer\">2 Jo 13</a> (veja <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"κυρία\" data-meanings=\"senhora; dama\">κυρία</span>); Hm 9:9 v.l. por <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"θυγάτηρ\" data-meanings=\"filha\">θυγάτηρ</span>.\n<strong>c.</strong> De condição ou circunstância, “irmã”: do pesar, <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀδελφή ἐστιν τῆς διψυχίας\" data-meanings=\"é irmã da duplicidade/dúvida\">ἀδελφή ἐστιν τῆς διψυχίας</span> Hm 10, 1, 1 s. (paralelos: Alceu; <em>Paroem. Gr. Append.</em> 3, 12; Platão, <em>Rep.</em> 3, 404b; Cebes 16, 2; Herm. Wr. 9, 1c). — DELG s.v. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀδελφός\" data-meanings=\"irmão\">ἀδελφός</span>. M-M. TW.\n</p></section></article><article id=\"entry-adelphoktonia-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀδελφοκτονία</h1><div class=\"entry-meta\"><span class=\"greek\">ας, ἡ</span><span class=\"separator\">·</span><span class=\"transliteration\">⟦adelphoktonía⟧</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">\n(Fílon, <em>De Jos.</em> 13; Jos., <em>Bell.</em> 1, 606; <em>Ant.</em> 17, 60; 91; Tat. 34, 1.) <strong>Fratricídio</strong>, de Caim (Fílon, <em>Agric.</em> 21), 1 Cl 4:7.\n</p></section></article><article id=\"entry-adelphos-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀδελφός</h1><div class=\"entry-meta\"><span class=\"greek\">οῦ, ὁ</span><span class=\"separator\">·</span><span class=\"transliteration\">⟦adelphós⟧</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">\n(Homero [<span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀδελφεός\" data-meanings=\"irmão; forma homérica\">ἀδελφεός</span>] +; segundo B-D-F §13; Schwyzer I 555; Mlt-H. II 58; P. Katz, TLZ 83, 1958, 315 s., o vocativo <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἄδελφε\" data-meanings=\"irmão!\">ἄδελφε</span> deveria receber acento na antepenúltima em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.9.17\" target=\"_blank\" rel=\"noopener noreferrer\">At 9.17</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.21.20\" target=\"_blank\" rel=\"noopener noreferrer\">21.20</a>, contrariamente à prática das edições; também GPt 2:5.)\n<span class=\"sense-number\">1.</span> <strong>Homem proveniente do mesmo ventre que a pessoa de referência, irmão</strong>: <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.1.2\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 1.2</a>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.1.11\" target=\"_blank\" rel=\"noopener noreferrer\">11</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.4.18\" target=\"_blank\" rel=\"noopener noreferrer\">4.18</a>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.4.21\" target=\"_blank\" rel=\"noopener noreferrer\">21</a> e outros; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"τὸν ἀ. τ. ἴδιον\" data-meanings=\"seu próprio irmão\">τὸν ἀ. τ. ἴδιον</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.1.41\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 1.41</a> (veja Jos., <em>Ant.</em> 11, 300).\nDos irmãos de Jesus: passagens como <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/GEN.13.8\" target=\"_blank\" rel=\"noopener noreferrer\">Gn 13.8</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/GEN.14.14\" target=\"_blank\" rel=\"noopener noreferrer\">14.14</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/GEN.24.48\" target=\"_blank\" rel=\"noopener noreferrer\">24.48</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/GEN.29.12\" target=\"_blank\" rel=\"noopener noreferrer\">29.12</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/LEV.10.4\" target=\"_blank\" rel=\"noopener noreferrer\">Lv 10.4</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/1CH.9.6\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cr 9.6</a> não estabelecem o sentido “primo” para <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀ.\" data-meanings=\"ἀδελφός\">ἀ.</span>; mostram apenas que, ao verter o hebraico <bdi class=\"hebrew hebrew-token tooltip-trigger\" lang=\"he\" dir=\"rtl\" tabindex=\"0\" data-tooltip-type=\"hebrew\" data-tooltip-label=\"אָח\" data-transliteration=\"ʾāḥ\" data-meanings=\"irmão|parente masculino\">אָח</bdi>, <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀ.\" data-meanings=\"ἀδελφός\">ἀ.</span> é ocasionalmente usado de modo amplo para parentes masculinos de vários graus. O caso de <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀδελφή\" data-meanings=\"irmã\">ἀδελφή</span> [q.v. 1] é semelhante: <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/GEN.24.59\" target=\"_blank\" rel=\"noopener noreferrer\">Gn 24.59 s.</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/TOB.8.4\" target=\"_blank\" rel=\"noopener noreferrer\">Tb 8.4</a>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/TOB.8.7\" target=\"_blank\" rel=\"noopener noreferrer\">7</a> [compare <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/TOB.7.15\" target=\"_blank\" rel=\"noopener noreferrer\">7.15</a>]; Jos., <em>Ant.</em> 1, 211 [<span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀδελφή = ἀδελφοῦ παῖς\" data-meanings=\"irmã = filha do irmão\">ἀδελφή = ἀδελφοῦ παῖς</span>]. Semelhantemente, M. Ant. 1, 14, 1 usa <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀ.\" data-meanings=\"irmão\">ἀ.</span> para seu cunhado Severo; uso ocasional também nos papiros: J. Collins, TS 5, 1944, 484–494; V. Tscherikover, HTR 1942, 25–44. — <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.12.46\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 12.46 s.</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.13.55\" target=\"_blank\" rel=\"noopener noreferrer\">13.55</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.3.31\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 3.31 s.</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.2.12\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 2.12</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.7.3\" target=\"_blank\" rel=\"noopener noreferrer\">7.3</a>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.7.5\" target=\"_blank\" rel=\"noopener noreferrer\">5</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.1.14\" target=\"_blank\" rel=\"noopener noreferrer\">At 1.14</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.9.5\" target=\"_blank\" rel=\"noopener noreferrer\">1 Co 9.5</a>. Tiago, <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ὁ ἀδελφὸς τοῦ κυρίου\" data-meanings=\"o irmão do Senhor\">ὁ ἀδελφὸς τοῦ κυρίου</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.1.19\" target=\"_blank\" rel=\"noopener noreferrer\">Gl 1.19</a>.\nO plural também pode significar <strong>irmãos e irmãs</strong> (Eur., <em>El.</em> 536; Andoc. 1, 47; Anton. Diog. 3; POxy 713, 21 s. [97 d.C.]; escólio a Nicandro, <em>Ther.</em> 11; os <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"θεοὶ Ἀδελφοί\" data-meanings=\"Deuses Irmãos\">θεοὶ Ἀδελφοί</span>, casal real de irmão e irmã entre os Ptolomeus: OGI 50, 2 e papiros). Nesses exemplos há um irmão e uma irmã; mas há também passagens em que <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀδελφοί\" data-meanings=\"irmãos; irmãos e irmãs\">ἀδελφοί</span> significa irmãos e irmãs em qualquer sequência escolhida pelo autor (Polyb. 10, 18, 15; Epict. 1, 12, 20; 1, 22, 10; 4, 1, 111; Artem. 3, 31; Ptolem., <em>Apotel.</em> 3, 6; Diog. L. 7, 108; 120; 10, 18; em PMich 214, 12 [296 d.C.] parece até mais geral = “teus parentes”). Portanto, em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.21.16\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 21.16</a> não há dúvida de que <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀδελφοί\" data-meanings=\"irmãos e irmãs\">ἀδελφοί</span> = irmãos e irmãs; mas há alguma margem de incerteza no caso dos <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀδελφοί\" data-meanings=\"irmãos\">ἀδελφοί</span> de Jesus em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.12.46\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 12.46 s.</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.3.31\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 3.31</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.2.12\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 2.12</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.7.3\" target=\"_blank\" rel=\"noopener noreferrer\">7.3</a>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.7.5\" target=\"_blank\" rel=\"noopener noreferrer\">5</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.1.14\" target=\"_blank\" rel=\"noopener noreferrer\">At 1.14</a>.\n<span class=\"sense-number\">2.</span> <strong>Pessoa vista como irmão em termos de afinidade estreita, irmão, companheiro, membro, associado</strong>, extensão figurada de 1.\n<strong>a.</strong> Alguém que compartilha crenças. Jesus chama “irmão” todo aquele que lhe é devotado, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.12.50\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 12.50</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.3.35\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 3.35</a>, especialmente seus discípulos, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.28.10\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 28.10</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.20.17\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 20.17</a>; daí, em geral, os que estão em tal comunhão espiritual, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.25.40\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 25.40</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.2.12\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 2.12</a> (<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/PSA.21.23\" target=\"_blank\" rel=\"noopener noreferrer\">Sl 21.23</a>), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.2.17\" target=\"_blank\" rel=\"noopener noreferrer\">17</a> e outros. De relação com mulher que não a de marido, Hs 9, 11, 3 e outros; 2 Cl 12:5.\nDe membros de uma comunidade religiosa: paralelos em PParis 20 [séc. II a.C.], UPZ 162 I, 20 [117 a.C.], IG XIV 956 B, 11 s., IPontEux II 449 s., papiro de mistério em APF 13 (1939), 212; essênios em Jos., <em>Bell.</em> 2, 122; Vett. Val. 172, 31; Cleopatra l. 94; veja G. Milligan sobre <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.1.4\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ts 1.4</a>; Ltzm., Hdb. sobre <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.1.13\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 1.13</a> e demais bibliografia citada pelo BDAG. Assim, entre cristãos, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.8.29\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 8.29</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.5.11\" target=\"_blank\" rel=\"noopener noreferrer\">1 Co 5.11</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.6.23\" target=\"_blank\" rel=\"noopener noreferrer\">Ef 6.23</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.6.2\" target=\"_blank\" rel=\"noopener noreferrer\">1 Tm 6.2</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.6.3\" target=\"_blank\" rel=\"noopener noreferrer\">At 6.3</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.9.30\" target=\"_blank\" rel=\"noopener noreferrer\">9.30</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.10.23\" target=\"_blank\" rel=\"noopener noreferrer\">10.23</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.1.9\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 1.9</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.12.10\" target=\"_blank\" rel=\"noopener noreferrer\">12.10</a>; IEph 10:3; ISm 12:1 e outros. Especialmente com nomes próprios, indicando participação na comunidade cristã: <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.16.23\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 16.23</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.1.1\" target=\"_blank\" rel=\"noopener noreferrer\">1 Co 1.1</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.16.12\" target=\"_blank\" rel=\"noopener noreferrer\">16.12</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.1.1\" target=\"_blank\" rel=\"noopener noreferrer\">2 Co 1.1</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.2.25\" target=\"_blank\" rel=\"noopener noreferrer\">Fp 2.25</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.1.1\" target=\"_blank\" rel=\"noopener noreferrer\">Cl 1.1</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.4.7\" target=\"_blank\" rel=\"noopener noreferrer\">4.7</a>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.4.9\" target=\"_blank\" rel=\"noopener noreferrer\">9</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.3.2\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ts 3.2</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHM.1.1\" target=\"_blank\" rel=\"noopener noreferrer\">Fm 1</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.5.12\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pe 5.12</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2PE.3.15\" target=\"_blank\" rel=\"noopener noreferrer\">2 Pe 3.15</a>; AcPl Ha 1, 30 e outros. Plenamente, <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀδελφὸς ἐν κυρίῳ\" data-meanings=\"irmão no Senhor\">ἀδελφὸς ἐν κυρίῳ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.1.14\" target=\"_blank\" rel=\"noopener noreferrer\">Fp 1.14</a>. Frequente em tratamento direto: 1 Cl 1:1; 4:7; 13:1; 33:1; 2 Cl 20:2 e outros; B 2:10; 3:6 e outros; IRo 6:2; Hv 2, 4, 1; 3, 1, 1; 4; AcPl Ha 7, 4; 8, 21; AcPlCor 1:16. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀδελφοί μου\" data-meanings=\"meus irmãos\">ἀδελφοί μου</span> B 4:14; 5:5; 6:15; IEph 16:1; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἄνδρες ἀ.\" data-meanings=\"homens irmãos\">ἄνδρες ἀ.</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.1.16\" target=\"_blank\" rel=\"noopener noreferrer\">At 1.16</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.15.7\" target=\"_blank\" rel=\"noopener noreferrer\">15.7</a>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.15.13\" target=\"_blank\" rel=\"noopener noreferrer\">13</a>; 1 Cl 14:1; 37:1; 43:4; 62:1. Interpretar <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀ.\" data-meanings=\"irmãos\">ἀ.</span> em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.15.23\" target=\"_blank\" rel=\"noopener noreferrer\">At 15.23</a> como “colega” é especulativo; interpretar <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀ.\" data-meanings=\"irmãos\">ἀ.</span> em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/3JN.1.5\" target=\"_blank\" rel=\"noopener noreferrer\">3 Jo 5</a> e <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/3JN.1.10\" target=\"_blank\" rel=\"noopener noreferrer\">10</a> como pregadores itinerantes baseia-se inteiramente no contexto.\n<strong>b.</strong> <strong>Compatriota</strong> (compare Pla., <em>Menex.</em> 239a; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/LEV.10.4\" target=\"_blank\" rel=\"noopener noreferrer\">Lv 10.4</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/DEU.15.3\" target=\"_blank\" rel=\"noopener noreferrer\">Dt 15.3</a>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/DEU.15.12\" target=\"_blank\" rel=\"noopener noreferrer\">12</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/DEU.17.15\" target=\"_blank\" rel=\"noopener noreferrer\">17.15</a> e outros; Fílon, <em>Spec. Leg.</em> 2, 79 s.; Jos., <em>Ant.</em> 10, 201): <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.2.29\" target=\"_blank\" rel=\"noopener noreferrer\">At 2.29</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.3.17\" target=\"_blank\" rel=\"noopener noreferrer\">3.17</a>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.3.22\" target=\"_blank\" rel=\"noopener noreferrer\">22</a> (<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/DEU.18.15\" target=\"_blank\" rel=\"noopener noreferrer\">Dt 18.15</a>); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.7.2\" target=\"_blank\" rel=\"noopener noreferrer\">At 7.2</a>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.7.23\" target=\"_blank\" rel=\"noopener noreferrer\">23</a> (<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/EXO.2.11\" target=\"_blank\" rel=\"noopener noreferrer\">Êx 2.11</a>), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.7.25\" target=\"_blank\" rel=\"noopener noreferrer\">25 s.</a> e outros; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.9.3\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 9.3</a>.\n<strong>c.</strong> Sem referência a nacionalidade ou fé comuns, <strong>próximo</strong> (de amigo íntimo, X., <em>An.</em> 7, 2, 25; 38; especificamente “próximo” em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/GEN.9.5\" target=\"_blank\" rel=\"noopener noreferrer\">Gn 9.5</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/LEV.19.17\" target=\"_blank\" rel=\"noopener noreferrer\">Lv 19.17</a> e outros): <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.5.22\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 5.22 ss.</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.7.3\" target=\"_blank\" rel=\"noopener noreferrer\">7.3 ss.</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.18.15\" target=\"_blank\" rel=\"noopener noreferrer\">18.15</a>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.18.21\" target=\"_blank\" rel=\"noopener noreferrer\">21</a>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.18.35\" target=\"_blank\" rel=\"noopener noreferrer\">35</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.6.41\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 6.41 s.</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.17.3\" target=\"_blank\" rel=\"noopener noreferrer\">17.3</a>; B 19:4; Hm 2:2 e outros.\n<strong>d.</strong> Forma de tratamento usada por rei a pessoas de posição muito elevada (OGI 138, 3; 168, 26; 36 [séc. II a.C.]; Jos., <em>Ant.</em> 13, 45; 126): Herodes diz <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀδελφὲ Πιλᾶτε\" data-meanings=\"irmão Pilatos\">ἀδελφὲ Πιλᾶτε</span> GPt 2:5.\n— J. O’Callaghan, “El vocativo sing. de ἀδελφός”, <em>Biblica</em> 52, 1971, 217–225. — B. 107. DELG. M-M. EDNT. TW. Sv.\n</p></section></article><article id=\"entry-adelphotes-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀδελφότης</h1><div class=\"entry-meta\"><span class=\"greek\">ητος, ἡ</span><span class=\"separator\">·</span><span class=\"transliteration\">⟦adelphótēs⟧</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">\n(B-D-F §110, 1; Mlt-H. 367; DELG s.v. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀδελφός\" data-meanings=\"irmão\">ἀδελφός</span>.)\n<span class=\"sense-number\">1.</span> <strong>Grupo de companheiros crentes, fraternidade, comunidade</strong> (compare <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/4MA.9.23\" target=\"_blank\" rel=\"noopener noreferrer\">4 Mc 9.23</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/4MA.10.3\" target=\"_blank\" rel=\"noopener noreferrer\">10.3</a>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/4MA.10.15\" target=\"_blank\" rel=\"noopener noreferrer\">15</a>; inscrição frígia [séc. III d.C., em Harnack, <em>Mission</em>⁴ 1924, 773 n.] <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"εἰρήνη πᾶσι τ. ἀδελφοῖς, εἰρήνη πάσῃ τ. ἀδελφότητι\" data-meanings=\"paz a todos os irmãos, paz a toda a fraternidade\">εἰρήνη πᾶσι τ. ἀδελφοῖς, εἰρήνη πάσῃ τ. ἀδελφότητι</span>), da comunidade cristã, cujos membros são <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀδελφοί\" data-meanings=\"irmãos\">ἀδελφοί</span> e <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀδελφαί\" data-meanings=\"irmãs\">ἀδελφαί</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.5.9\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pe 5.9</a>; 1 Cl 2:4. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"τὴν ἀ. ἀγαπᾶν\" data-meanings=\"amar a fraternidade\">τὴν ἀ. ἀγαπᾶν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.2.17\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pe 2.17</a> (sobre o significado social, veja J. Elliott, <em>A Home for the Homeless</em>, 1981 [com nova introdução, 1990]).\n<span class=\"sense-number\">2.</span> <strong>Afeição mútua como a de irmãos ou irmãs, afeição fraternal</strong> (Dio Chrys. 21 [38], 15; Vett. Val. p. 2, 28; 4, 5; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/1MA.12.10\" target=\"_blank\" rel=\"noopener noreferrer\">1 Mc 12.10</a>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/1MA.12.17\" target=\"_blank\" rel=\"noopener noreferrer\">17</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/4MA.13.27\" target=\"_blank\" rel=\"noopener noreferrer\">4 Mc 13.27</a>): <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀ. συντηρεῖν\" data-meanings=\"preservar a afeição fraternal\">ἀ. συντηρεῖν</span> Hm 8:10 (v.l. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀγαθότητα\" data-meanings=\"bondade\">ἀγαθότητα</span> cód. Athous). — M-M. TW. Sv.\n</p></section></article><article id=\"entry-adeos-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀδεῶς</h1><div class=\"entry-meta\"><span>advérbio</span><span class=\"separator\">·</span><span class=\"transliteration\">⟦adeō̂s⟧</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">\n(Heródoto+; Aristoph., <em>Vesp.</em> 359; Manetho: 609 Fgm. 9, 100; também IG IV, 597; PMich 425, 20 [ambos séc. II d.C.]; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/3MA.2.32\" target=\"_blank\" rel=\"noopener noreferrer\">3 Mc 2.32</a>; Fílon, <em>Cherub.</em> 99; Jos., <em>Ant.</em> 6, 313; 18, 370; Just., <em>A</em> II, 12, 5.) <strong>Sem medo/perturbação</strong>: <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"προσεύχεσθαι\" data-meanings=\"orar\">προσεύχεσθαι</span> MPol 7:2; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"λαμβάνειν\" data-meanings=\"receber\">λαμβάνειν</span> ITr 6:2. — DELG s.v. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"δείδω\" data-meanings=\"temer\">δείδω</span>.\n</p></section></article><article id=\"entry-adelos-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἄδηλος</h1><div class=\"entry-meta\"><span class=\"greek\">ον</span><span class=\"separator\">·</span><span class=\"transliteration\">⟦ádēlos⟧</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">\n(Hesíodo e outros; inscrições; PLond 940, 23; POxy 118, 5 s.; PLips 37, 23; PGM 4, 3048; LXX, Fílon; Jos., <em>Bell.</em> 7, 115; <em>Ant.</em> 1, 268; 13, 151; Ath. 5, 2.)\n<span class=\"sense-number\">1.</span> <strong>Relativo ao que não é prontamente aparente, não claro, latente, invisível</strong> (Sófocles e outros; OGI 218, 129 [séc. III a.C.]): <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"τὰ μνημεῖα τὰ ἄ.\" data-meanings=\"os túmulos não aparentes/ocultos\">τὰ μνημεῖα τὰ ἄ.</span>, “sepulturas perigosamente ocultas”, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.11.44\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 11.44</a>; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"τὰ ἄ. δηλοῦν\" data-meanings=\"revelar as coisas ocultas\">τὰ ἄ. δηλοῦν</span> 1 Cl 18:6 (<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/PSA.50.8\" target=\"_blank\" rel=\"noopener noreferrer\">Sl 50.8</a>). <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"πῶς ἡ πίστις εὑρετέα τῶν ἀδήλων ἡ φαινομένη τοῦ ἀγεννήτου πατρός\" data-meanings=\"como deve ser encontrada a fé nas coisas invisíveis, a que se manifesta em relação ao Pai não gerado\">πῶς ἡ πίστις εὑρετέα τῶν ἀδήλων ἡ φαινομένη τοῦ ἀγεννήτου πατρός</span> — reconstrução de POxy 1081, 32–34 com base no copta SJCh 90, 12.\n<span class=\"sense-number\">2.</span> <strong>Relativo ao que não é claramente definido, indistinto</strong> (Polyb. 8, 1, 2 <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἄ. ἐλπίδες\" data-meanings=\"esperanças vagas\">ἄ. ἐλπίδες</span>; semelhantemente Maximus Tyr. 36, 4a), de trombeta: <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀ. φωνὴν διδόναι\" data-meanings=\"produzir som indistinto\">ἀ. φωνὴν διδόναι</span>, de modo que o sinal não possa ser reconhecido, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.14.8\" target=\"_blank\" rel=\"noopener noreferrer\">1 Co 14.8</a>. — DELG s.v. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"δῆλος\" data-meanings=\"claro; manifesto\">δῆλος</span>. M-M.\n</p></section></article><article id=\"entry-adelotes-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀδηλότης</h1><div class=\"entry-meta\"><span class=\"greek\">ητος, ἡ</span><span class=\"separator\">·</span><span class=\"transliteration\">⟦adēlótēs⟧</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">\n(Protagoras [séc. V a.C.] e outros; Polyb., Plut., Fílon e outros.) <strong>Incerteza</strong>: <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἐλπίζειν ἐπὶ πλούτου ἀδηλότητι\" data-meanings=\"depositar esperança na incerteza da riqueza\">ἐλπίζειν ἐπὶ πλούτου ἀδηλότητι</span>, “depositar esperança numa coisa tão incerta como a riqueza”, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.6.17\" target=\"_blank\" rel=\"noopener noreferrer\">1 Tm 6.17</a> (Dio Chrys. 16, 8; B-D-F §165). Veja <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"δῆλος\" data-meanings=\"claro; manifesto\">δῆλος</span>.\n</p></section></article><article id=\"entry-adelos-adv-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀδήλως</h1><div class=\"entry-meta\"><span>advérbio</span><span class=\"separator\">·</span><span class=\"transliteration\">⟦adḗlōs⟧</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">\nAdvérbio de <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἄδηλος\" data-meanings=\"não claro; indistinto\">ἄδηλος</span> (Tucídides e outros; Plut.; Aelian, <em>VH</em> 1, 21 p. 10, 4; Fílon, <em>Conf. Lingu.</em> 119), <strong>incertamente</strong> (Ps.-Phocyl. 25; 117). De uma corrida: <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"οὕτως τρέχω ὡς οὐκ ἀδήλως\" data-meanings=\"corro assim, não sem alvo\">οὕτως τρέχω ὡς οὐκ ἀδήλως</span>, “não sem objetivo”, isto é, não como quem não tem meta fixa, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.9.26\" target=\"_blank\" rel=\"noopener noreferrer\">1 Co 9.26</a> (compare Ps.-Phocyl. 28 <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἄδηλος πλοῦς\" data-meanings=\"navegação incerta\">ἄδηλος πλοῦς</span>). PEg² 61 (contexto fragmentário).\n</p></section></article><article id=\"entry-ademoneo-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀδημονέω</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦adēmonéō⟧</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">\n(Hipócrates e outros; Platão, Xenofonte; TestAbr A 7, p. 84, 9 [Stone p. 16]; Jos., <em>Ant.</em> 15, 211; 388; POxy 298, 45 [séc. I d.C.] <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"λίαν ἀδημονοῦμεν χάριν τῆς θρεπτῆς Σαραποῦτος\" data-meanings=\"estamos muito aflitos por causa da criada Sarapous\">λίαν ἀδημονοῦμεν χάριν τῆς θρεπτῆς Σαραποῦτος</span>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/JOB.18.20\" target=\"_blank\" rel=\"noopener noreferrer\">Jó 18.20</a> Aq.; Sym. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/PSA.60.3\" target=\"_blank\" rel=\"noopener noreferrer\">Sl 60.3</a> e outros.) <strong>Estar em ansiedade, estar angustiado, perturbado</strong>: com <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"λυπεῖσθαι\" data-meanings=\"entristecer-se\">λυπεῖσθαι</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.26.37\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 26.37</a>; com <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἐκθαμβεῖσθαι\" data-meanings=\"ficar profundamente perturbado\">ἐκθαμβεῖσθαι</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.14.33\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 14.33</a>; seguido de <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"διότι\" data-meanings=\"porque\">διότι</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.2.26\" target=\"_blank\" rel=\"noopener noreferrer\">Fp 2.26</a>. — M. Harl, <em>La Bible et les Pères</em>, 1971, 257. — DELG. M-M.\n</p></section></article><article id=\"entry-hades-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ᾅδης</h1><div class=\"entry-meta\"><span class=\"greek\">ου, ὁ</span><span class=\"separator\">·</span><span class=\"transliteration\">⟦hádēs⟧</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">\n(Com várias grafias desde Homero.)\n<span class=\"sense-number\">1.</span> Originalmente nome próprio do deus do mundo inferior, “Hades”; depois <strong>o mundo inferior, Hades, como lugar dos mortos</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.2.27\" target=\"_blank\" rel=\"noopener noreferrer\">At 2.27</a>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.2.31\" target=\"_blank\" rel=\"noopener noreferrer\">31</a> (<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/PSA.15.10\" target=\"_blank\" rel=\"noopener noreferrer\">Sl 15.10</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/ECC.9.10\" target=\"_blank\" rel=\"noopener noreferrer\">Ec 9.10</a>; PGM 1, 179; 16, 8; Fílon, <em>Mos.</em> 1, 195; Jos., <em>Bell.</em> 1, 596; <em>Ant.</em> 6, 332). Do peixe de Jonas, <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἐκ τοῦ κατωτάτου ᾅδου\" data-meanings=\"das profundezas do Hades\">ἐκ τοῦ κατωτάτου ᾅδου</span>. Nas profundezas, contrastado com o céu: <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἕως (τοῦ) ᾅδου\" data-meanings=\"até o Hades\">ἕως (τοῦ) ᾅδου</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.11.23\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 11.23</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.10.15\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 10.15</a> (PsSol 15:10; compare <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/ISA.14.11\" target=\"_blank\" rel=\"noopener noreferrer\">Is 14.11</a>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/ISA.14.15\" target=\"_blank\" rel=\"noopener noreferrer\">15</a>); <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἐν τῷ ᾅδῃ\" data-meanings=\"no Hades\">ἐν τῷ ᾅδῃ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.16.23\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 16.23</a>; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἐν Ἅιδου\" data-meanings=\"no Hades\">ἐν Ἅιδου</span> ApcPt Rainer.\nAcessível por portas — embora o plural também seja usado quando só uma porta é concebida —, daí <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"πύλαι ᾅδου\" data-meanings=\"portas do Hades\">πύλαι ᾅδου</span> (Hom., <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/ISA.38.10\" target=\"_blank\" rel=\"noopener noreferrer\">Is 38.10</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/WIS.16.13\" target=\"_blank\" rel=\"noopener noreferrer\">Sb 16.13</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/3MA.5.51\" target=\"_blank\" rel=\"noopener noreferrer\">3 Mc 5.51</a>; PsSol 16:2; Lucian, <em>Menipp.</em> 6), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.16.18\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 16.18</a> (veja <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"πέτρα\" data-meanings=\"rocha\">πέτρα</span> 1b e <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"πύλη\" data-meanings=\"porta\">πύλη</span> a). É trancado: <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἔχω τὰς κλεῖς τοῦ θανάτου καὶ τοῦ ᾅδου\" data-meanings=\"tenho as chaves da morte e do Hades\">ἔχω τὰς κλεῖς τοῦ θανάτου καὶ τοῦ ᾅδου</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.1.18\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 1.18</a> (genitivos objetivos ou possessivos; no último caso, morte e Hades são personificados; compare Ps.-Apollod. 3, 12, 6, 10; SEG VIII 574, 3). <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ὠδῖνες τοῦ ᾅδου\" data-meanings=\"dores do Hades\">ὠδῖνες τοῦ ᾅδου</span> (<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/PSA.17.6\" target=\"_blank\" rel=\"noopener noreferrer\">Sl 17.6</a>) Pol 1:2; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.2.24\" target=\"_blank\" rel=\"noopener noreferrer\">At 2.24</a> v.l. por <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"θανάτου\" data-meanings=\"da morte\">θανάτου</span>. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"εἰς ᾅδου\" data-meanings=\"ao Hades\">εἰς ᾅδου</span> (subentenda-se <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"δόμους\" data-meanings=\"moradas\">δόμους</span>; B-D-F §162, 8; Homero e outros; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/BAR.3.11\" target=\"_blank\" rel=\"noopener noreferrer\">Br 3.11</a>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/BAR.3.19\" target=\"_blank\" rel=\"noopener noreferrer\">19</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/TOB.3.10\" target=\"_blank\" rel=\"noopener noreferrer\">Tb 3.10</a>; En 102:5; 103:7; Ar. 11, 3), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.2.31\" target=\"_blank\" rel=\"noopener noreferrer\">At 2.31</a> v.l.; 1 Cl 4:12; 51:4; compare Just., <em>D.</em> 99, 3; Mel., Fgm. 8b, 44; Iambl., <em>Vi. Pyth.</em> 30, 179; Hierocles 14, 451.\n<span class=\"sense-number\">2.</span> <strong>Hades personificado</strong> (talvez derivado do uso do AT; compare a divindade semítica Mot), com <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"θάνατος\" data-meanings=\"morte\">θάνατος</span> (compare <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/ISA.28.15\" target=\"_blank\" rel=\"noopener noreferrer\">Is 28.15</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/JOB.38.17\" target=\"_blank\" rel=\"noopener noreferrer\">Jó 38.17</a>; Mel., <em>P.</em> 102, 782): <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.6.8\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 6.8</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.20.13\" target=\"_blank\" rel=\"noopener noreferrer\">20.13 s.</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.15.55\" target=\"_blank\" rel=\"noopener noreferrer\">1 Co 15.55</a> v.l.\n— G. Beer, “D. bibl. Hades”, <em>H. Holtzmann Festschr.</em> 1902, 1–30; E. Rohde, <em>Psyche</em>⁴ I 54 ss.; 309 ss.; A. Dieterich, <em>Nekyia</em> 1893; Bousset, <em>Rel.</em>³ 285 s.; 293 ss.; Billerbeck IV 1016–1029; A. Heidel, <em>The Gilgamesh Epic and OT Parallels</em>², 1949, 173–191; L. Sullivan, <em>Theological Studies</em> 10, 1949, 62 ss.; J. Bremmer, DDD 725 s. Veja também <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"πνεῦμα\" data-meanings=\"espírito\">πνεῦμα</span> 2 e 4c. — B. 1485. Frisk s.v. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"Ἅιδης\" data-meanings=\"Hades\">Ἅιδης</span>. M-M. TW.\n</p></section></article><article id=\"entry-adiakritos-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀδιάκριτος</h1><div class=\"entry-meta\"><span class=\"greek\">ον</span><span class=\"separator\">·</span><span class=\"transliteration\">⟦adiákritos⟧</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">\n(Hipócrates e outros; Polyb. 15, 12, 9; OGI 509, 8; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/PRO.25.1\" target=\"_blank\" rel=\"noopener noreferrer\">Pv 25.1</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/GEN.1.2\" target=\"_blank\" rel=\"noopener noreferrer\">Gn 1.2</a> Sym.; Fílon, <em>Spec. Leg.</em> 3, 57 e outros; vários sentidos em Lghtf. sobre IEph 3:2; como virtude humana também Ptolem., <em>Apotel.</em> 3, 14, 29.)\n<span class=\"sense-number\">1.</span> <strong>Relativo a não ser julgador ou divisivo, não julgador, não divisivo, imparcial</strong> (<em>Anecd. Gr.</em> 213, 22), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.3.17\" target=\"_blank\" rel=\"noopener noreferrer\">Tg 3.17</a> (a estrutura literária, com clímax em 4:11 s., aponta fortemente nesta direção; compare NRSV “without a trace of partiality”; Dibelius-Greeven, comentário Hermeneia, 1964, 214, com referência ao uso em Inácio: “simples” ou “harmonioso”). Semelhantemente IEph 3:2; IMg 15.\n<span class=\"sense-number\">2.</span> Alguns preferem: <strong>relativo a não estar incerto, firme, sem vacilar</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.3.17\" target=\"_blank\" rel=\"noopener noreferrer\">Tg 3.17</a> (compare <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.1.6\" target=\"_blank\" rel=\"noopener noreferrer\">Tg 1.6</a>; J. Mayor, comentário ad loc.: “single-minded”, “unhesitating”; RSV “without uncertainty”; mas veja 1 acima); <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἐν ὑπομονῇ\" data-meanings=\"em perseverança\">ἐν ὑπομονῇ</span> ITr 1:1. — DELG s.v. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"κρίνω\" data-meanings=\"julgar\">κρίνω</span>. M-M. TW.\n</p></section></article><article id=\"entry-adiakritos-adv-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀδιακρίτως</h1><div class=\"entry-meta\"><span>advérbio</span><span class=\"separator\">·</span><span class=\"transliteration\">⟦adiakrítōs⟧</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">\n(<em>Anecd. Gr.</em> 352; Proclus sobre Pla., <em>Crat.</em> p. 91, 13; escólio sobre Apollon. Rhod. 2, 62; Fílon, Fgm. 105 Harris [1886]; TestZeb 7:2; POxy 715, 36 [131 d.C.] = Wilcken, APF 4, 1908, 254.) <strong>Sem vacilar</strong>, IRo ins.; IPhld ins. (veja <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀδιάκριτος\" data-meanings=\"imparcial; firme\">ἀδιάκριτος</span>).\n</p></section></article><article id=\"entry-adialeiptos-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀδιάλειπτος</h1><div class=\"entry-meta\"><span class=\"greek\">ον</span><span class=\"separator\">·</span><span class=\"transliteration\">⟦adiáleiptos⟧</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">\n(Ps.-Pla., <em>Tim. Locr.</em> 98e e outros; SIG 1104, 35; PTebt 27, 45 [113 a.C.]; PGM 8, 32; EpArist 84; Jos., <em>Bell.</em> 2, 155; 5, 31.) <strong>Incessante, constante</strong>: <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ὀδύνη\" data-meanings=\"dor\">ὀδύνη</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.9.2\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 9.2</a>; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"μνεία\" data-meanings=\"lembrança\">μνεία</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.1.3\" target=\"_blank\" rel=\"noopener noreferrer\">2 Tm 1.3</a>; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"προσευχαί\" data-meanings=\"orações\">προσευχαί</span> IPol 1:3; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀ. ἔχειν ὕδωρ\" data-meanings=\"ter água sem faltar\">ἀ. ἔχειν ὕδωρ</span> Hs 2:8; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἵνα ἀ. γένηται ἐν τῇ ζωῇ αὐτοῦ\" data-meanings=\"para que nada lhe falte em sua vida\">ἵνα ἀ. γένηται ἐν τῇ ζωῇ αὐτοῦ</span> Hs 2:6 (veja M. Dibelius ad loc.). — M-M.\n</p></section></article><article id=\"entry-adialeiptos-adv-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀδιαλείπτως</h1><div class=\"entry-meta\"><span>advérbio</span><span class=\"separator\">·</span><span class=\"transliteration\">⟦adialeíptōs⟧</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">\n(Desde Metrodoro, filósofo [sécs. IV/III a.C.]: PHercul 831, 8; Polyb. 9, 3, 8; SIG 1104, 15; 1171, 4; papiros desde o séc. II a.C. [Mayser 458]; 1, 2 e 3 Macabeus; EpArist 92; 294; Aristóbulo em Eus., <em>PE</em> 13, 12, 4; TestLevi 13:2; TestSol 3:7; Jos., <em>Bell.</em> 3, 164; 241; Just., <em>D.</em> 133, 6.) <strong>Constantemente, incessantemente</strong>: <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"μνείαν ποιεῖσθαι\" data-meanings=\"fazer menção; lembrar\">μνείαν ποιεῖσθαι</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.1.9\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 1.9</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.1.2\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ts 1.2</a>; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"εὐχαριστεῖν\" data-meanings=\"dar graças\">εὐχαριστεῖν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.2.13\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ts 2.13</a>; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"προσεύχεσθαι\" data-meanings=\"orar\">προσεύχεσθαι</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.5.17\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ts 5.17</a>; IEph 10:1; Hs 9, 11, 7; compare Pol 4:3. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"προσκαρτερεῖν τῇ ἐλπίδι\" data-meanings=\"perseverar na esperança\">προσκαρτερεῖν τῇ ἐλπίδι</span> Pol 8:1. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"διδόναι\" data-meanings=\"dar\">διδόναι</span> (de Deus) Hs 5, 4, 4 v.l. por <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀδιστάκτως\" data-meanings=\"sem hesitar; seguramente\">ἀδιστάκτως</span>. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"σκεπάζειν\" data-meanings=\"cobrir; proteger\">σκεπάζειν</span> Hs 9, 27, 2. — DELG s.v. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"λείπω\" data-meanings=\"deixar; faltar\">λείπω</span>.\n</p></section></article><article id=\"entry-adiaphthoria-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀδιαφθορία</h1><div class=\"entry-meta\"><span class=\"greek\">ας, ἡ</span><span class=\"separator\">·</span><span class=\"transliteration\">⟦adiaphthoría⟧</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">\n(O substantivo não se encontra em outra parte antes de Just., <em>A</em> II, 3, 7; mas <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀδιάφθορος\" data-meanings=\"incorruptível; íntegro\">ἀδιάφθορος</span> é bastante comum em Platão e outros, Fílon; ApcEsdr 1:20 p. 25, 14 Tdf.; Just., <em>A</em> I, 18, 3; Ath. 2, 3.) <strong>Sinceridade, integridade</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/TIT.2.7\" target=\"_blank\" rel=\"noopener noreferrer\">Tt 2.7</a> v.l. por <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀφθορία\" data-meanings=\"incorrupção; integridade\">ἀφθορία</span>, q.v. — DELG s.v. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"φθείρω\" data-meanings=\"corromper; destruir\">φθείρω</span>. M-M. s.v. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀδιάφθορος\" data-meanings=\"incorruptível; íntegro\">ἀδιάφθορος</span>.\n</p></section></article><article id=\"entry-adiegetos-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀδιήγητος</h1><div class=\"entry-meta\"><span class=\"greek\">ον</span><span class=\"separator\">·</span><span class=\"transliteration\">⟦adiḗgētos⟧</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">\n<strong>Indescritível</strong> (Xenofonte e outros; Ael. Aristid. 33, 30 K. = 51 p. 581 D.; PGM 1, 164; EpArist 89; 99; Just., <em>D.</em> 32, 2 [compare <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/ISA.53.8\" target=\"_blank\" rel=\"noopener noreferrer\">Is 53.8</a> = <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.8.33\" target=\"_blank\" rel=\"noopener noreferrer\">At 8.33</a>]). <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ὁ ἐν ἀγάπῃ ἀ.\" data-meanings=\"um homem de amor inexprimível\">ὁ ἐν ἀγάπῃ ἀ.</span>, “um homem de amor inexprimível”, IEph 1:3. — DELG s.v. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἡγέομαι\" data-meanings=\"considerar; conduzir\">ἡγέομαι</span>.\n</p></section></article>"};
